/**
 * Optional class features (invocations, maneuvers, metamagic, infusions, and the rest).
 * Generated by sourcebooks/build_optional_features.py. The picker reads the allowance
 * from this module.
 */

import features from '../data/optionalFeatures.json'
import progression from '../data/optionalFeatureProgression.json'
import type { Character, Edition, SensesGrant, SkillName } from '../types/dnd'
import { SKILL_TO_ABILITY, getModifier } from '../services/dataService'

export interface OptionalFeaturePrerequisite {
  level?: number
  classSlug?: string
  pact?: string
  spells?: string[]
  spellChoice?: string
  items?: string[]
  features?: string[]
  summary?: string
}

export interface OptionalFeatureGrant {
  featureType: string
  name: string
  count: number
}

export interface OptionalFeature {
  slug: string
  name: string
  edition: Edition
  source: string
  featureTypes: string[]
  featureTypeName: string
  classes: string[]
  description: string
  prerequisites?: OptionalFeaturePrerequisite[]
  spells?: string[]
  uses?: string
  grants?: OptionalFeatureGrant[]
  grantsFeat?: { count: number; category: string }
  skills?: string[]
  senses?: SensesGrant
  classFeatureVariant?: boolean
}

export interface OptionalFeatureProgression {
  classSlug: string
  edition: Edition
  subclassSlug: string | null
  featureType: string
  name: string
  /** Total known at each level. Index 0 is level 1. */
  knownByLevel: number[]
  required: { level: number; slugs: string[] }[]
}

export interface OptionalFeatureAllowance {
  featureType: string
  name: string
  known: number
  required: string[]
  /** How many more than the previous level. Present on picks-at-level results. */
  gain?: number
}

export const OPTIONAL_FEATURES = features as OptionalFeature[]
export const OPTIONAL_FEATURE_PROGRESSION = progression as OptionalFeatureProgression[]

const BY_SLUG = new Map(OPTIONAL_FEATURES.map(feature => [feature.slug, feature]))

/** 2024 characters keep a saved plain slug when that feature was reprinted. */
export const resolveOptionalFeatureSlug = (slug: string, edition?: Edition): string => {
  if (edition === '2024' && BY_SLUG.has(`${slug}-2024`)) return `${slug}-2024`
  return slug
}

export const getOptionalFeature = (slug?: string | null, edition?: Edition): OptionalFeature | undefined => {
  if (!slug) return undefined
  return BY_SLUG.get(resolveOptionalFeatureSlug(slug, edition))
}

/** Sheet clicks pass the display name. Prefer the character's edition when both printings share a name. */
export const findOptionalFeatureByName = (name: string, edition?: Edition): OptionalFeature | undefined => {
  const matches = OPTIONAL_FEATURES.filter(feature => feature.name === name)
  if (!edition) return matches[0]
  return matches.find(feature => feature.edition === edition) ?? matches[0]
}

export const optionalFeaturesOfType = (featureType: string, edition: Edition): OptionalFeature[] =>
  OPTIONAL_FEATURES.filter(feature => feature.edition === edition && feature.featureTypes.includes(featureType))

const knownAt = (row: OptionalFeatureProgression, level: number): number =>
  row.knownByLevel[Math.min(Math.max(level, 1), 20) - 1] ?? 0

/**
 * How many options of each kind the character knows at this level.
 * A subclass row adds to the class row. A selected feature that grants more
 * (Superior Technique grants one maneuver) adds on top while that feature is selected.
 */
export const optionalFeatureAllowance = (
  classSlug: string,
  edition: Edition,
  level: number,
  subclassSlug?: string | null,
  selected: string[] = [],
): OptionalFeatureAllowance[] => {
  const byType = new Map<string, OptionalFeatureAllowance>()
  for (const row of OPTIONAL_FEATURE_PROGRESSION) {
    if (row.classSlug !== classSlug || row.edition !== edition) continue
    if (row.subclassSlug && row.subclassSlug !== subclassSlug) continue
    const current = byType.get(row.featureType) ?? {
      featureType: row.featureType,
      name: row.name,
      known: 0,
      required: [],
    }
    current.known += knownAt(row, level)
    for (const required of row.required) {
      if (level >= required.level) current.required.push(...required.slugs)
    }
    byType.set(row.featureType, current)
  }

  for (const slug of selected) {
    for (const grant of getOptionalFeature(slug, edition)?.grants ?? []) {
      const current = byType.get(grant.featureType) ?? {
        featureType: grant.featureType,
        name: grant.name,
        known: 0,
        required: [],
      }
      current.known += grant.count
      byType.set(grant.featureType, current)
    }
  }

  return [...byType.values()].filter(row => row.known > 0)
}

/** Options gained on reaching `level` (the increase from the level before). */
export const optionalFeaturePicksAtLevel = (
  classSlug: string,
  edition: Edition,
  level: number,
  subclassSlug?: string | null,
  selected: string[] = [],
): OptionalFeatureAllowance[] => {
  const now = optionalFeatureAllowance(classSlug, edition, level, subclassSlug, selected)
  const previous = new Map(
    (level <= 1 ? [] : optionalFeatureAllowance(classSlug, edition, level - 1, subclassSlug, selected))
      .map(row => [row.featureType, row.known]),
  )
  return now
    .map(row => ({ ...row, gain: row.known - (previous.get(row.featureType) ?? 0) }))
    .filter(row => (row.gain ?? 0) > 0)
}

const hasPact = (pact: string, selected: string[], characterPact?: string | null): boolean => {
  if (characterPact && characterPact.toLowerCase() === pact) return true
  const needle = `pact-of-the-${pact}`
  return selected.some(slug => slug === needle || slug.startsWith(`${needle}-`))
}

/**
 * Why this feature cannot be taken. Spell, item, and renown requirements are shown
 * on the card and do not block the pick, because those choices happen elsewhere.
 */
export const optionalFeatureBlockedReason = (
  feature: OptionalFeature,
  level: number,
  classSlug: string,
  selected: string[],
  pact?: string | null,
): string | null => {
  for (const group of feature.prerequisites ?? []) {
    if (group.level && level < group.level) return `Requires level ${group.level}`
    if (group.classSlug && group.classSlug !== classSlug) return `Requires a ${group.classSlug}`
    if (group.pact && !hasPact(group.pact, selected, pact)) {
      return `Requires Pact of the ${group.pact[0].toUpperCase()}${group.pact.slice(1)}`
    }
    for (const required of group.features ?? []) {
      const resolved = resolveOptionalFeatureSlug(required, feature.edition)
      if (!selected.includes(required) && !selected.includes(resolved)) {
        return `Requires ${getOptionalFeature(resolved)?.name ?? required}`
      }
    }
  }
  return null
}

export const optionalFeaturesForPick = (
  featureType: string,
  edition: Edition,
  level: number,
  classSlug: string,
  selected: string[] = [],
  pact?: string | null,
): OptionalFeature[] =>
  optionalFeaturesOfType(featureType, edition).filter(feature =>
    !optionalFeatureBlockedReason(feature, level, classSlug, selected, pact))

const prettySlug = (slug: string): string => slug.replace(/-20\d\d$/, '').replace(/-/g, ' ')

/** Notes to show under an available feature (spells, items, renown). */
export const optionalFeatureNotes = (feature: OptionalFeature): string[] => {
  const notes: string[] = []
  for (const group of feature.prerequisites ?? []) {
    if (group.spells?.length) notes.push(`Spell: ${group.spells.map(prettySlug).join(' or ')}`)
    if (group.spellChoice) notes.push(group.spellChoice)
    if (group.items?.length) notes.push(group.items.join('; '))
    if (group.summary) notes.push(group.summary)
  }
  if (feature.uses) notes.push(`Uses ${feature.uses}`)
  return notes
}

export const creationNeedsOptionalFeatures = (
  classSlug: string | undefined,
  edition: Edition,
  level: number,
  subclassSlug?: string | null,
): boolean =>
  !!classSlug && optionalFeatureAllowance(classSlug, edition, level, subclassSlug).length > 0

/** True when this level-up grants a new option, including a subclass chosen in the same wizard. */
export const levelUpNeedsOptionalFeatures = (
  classSlug: string,
  edition: Edition,
  level: number,
  subclassSlug?: string | null,
  choosingSubclass = false,
): boolean => {
  if (optionalFeaturePicksAtLevel(classSlug, edition, level, subclassSlug).length > 0) return true
  if (!choosingSubclass) return false
  const subclasses = new Set(
    OPTIONAL_FEATURE_PROGRESSION
      .filter(row => row.classSlug === classSlug && row.edition === edition && row.subclassSlug)
      .map(row => row.subclassSlug as string),
  )
  return [...subclasses].some(slug => optionalFeaturePicksAtLevel(classSlug, edition, level, slug).length > 0)
}

/** A full random set of the options this class knows at `level`, including grants those options add. */
export function randomOptionalFeatures(
  classSlug: string,
  edition: Edition,
  level: number,
  subclassSlug?: string | null,
  pact?: string | null,
): { optionalFeatures: string[]; fightingStyle?: string; selectedFightingStyle: string | null; eldritchInvocations: string[] } {
  const provisional = optionalFeatureAllowance(classSlug, edition, level, subclassSlug, [])
  let context = [...new Set(provisional.flatMap(group => group.required))]
  const groups = optionalFeatureAllowance(classSlug, edition, level, subclassSlug, context)
  const next: string[] = []
  for (const group of groups) {
    const pool = optionalFeaturesForPick(group.featureType, edition, level, classSlug, context, pact).map(feature => feature.slug)
    const required = group.required.filter(slug => pool.includes(slug))
    const shuffled = pool.filter(slug => !required.includes(slug)).sort(() => Math.random() - 0.5)
    const picks = [...required, ...shuffled].slice(0, group.known)
    next.push(...picks)
    context = [...context, ...picks]
  }
  const optionalFeatures = [...new Set(next)]
  const features = optionalFeatures.map(slug => getOptionalFeature(slug, edition)).filter(feature => !!feature)
  const fightingStyle = features.find(feature => feature.featureTypes.some(type => type.startsWith('FS:')))?.slug
  return {
    optionalFeatures,
    fightingStyle,
    selectedFightingStyle: fightingStyle ?? null,
    eldritchInvocations: features.filter(feature => feature.featureTypes.includes('EI')).map(feature => feature.slug),
  }
}

export const optionalFeatureSelectionComplete = (
  groups: OptionalFeatureAllowance[],
  selected: string[],
  edition: Edition,
): boolean =>
  groups.every(group =>
    selected.filter(slug => getOptionalFeature(slug, edition)?.featureTypes.includes(group.featureType)).length === group.known)

/** Skills and senses stored on the feature. Spell text stays on the record. */
export const applyOptionalFeatureGrants = (character: Character, slugs: string[]): void => {
  for (const slug of slugs) {
    const feature = getOptionalFeature(slug, character.edition)
    if (!feature) continue
    for (const skill of feature.skills ?? []) {
      const entry = character.skills[skill as SkillName]
      const ability = SKILL_TO_ABILITY[skill as SkillName]
      if (!entry || entry.proficient || !ability) continue
      entry.proficient = true
      entry.value = getModifier(character.abilities[ability].score) + character.proficiencyBonus
    }
    if (feature.senses) {
      const senses: SensesGrant = { ...(character.senses ?? {}) }
      for (const key of Object.keys(feature.senses) as (keyof SensesGrant)[]) {
        senses[key] = Math.max(senses[key] ?? 0, feature.senses[key] ?? 0)
      }
      character.senses = senses
    }
  }
}
